// Combine the services from the config with the services billed in Cost Explorer (if enabled)
const cfg = $('Set AWS and Teams Config').first().json;
const manual = String(cfg.my_services || '').split(',').map(s => s.trim()).filter(Boolean);
let fromCe = [];
let source = 'your list in the config';

if (cfg.use_cost_explorer === true || cfg.use_cost_explorer === 'true') {
  const raw = $input.first().json;
  try {
    if (raw.error) {
      throw new Error(typeof raw.error === 'string' ? raw.error : (raw.error.message || JSON.stringify(raw.error)));
    }
    // Cost Explorer replies with application/x-amz-json-1.1, which n8n returns as text in `data`
    const res = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw;
    if (!res.ResultsByTime) throw new Error('Unexpected Cost Explorer response');
    const totals = {};
    for (const period of res.ResultsByTime) {
      for (const g of period.Groups || []) {
        const name = g.Keys?.[0];
        if (!name || name === 'Tax') continue;
        totals[name] = (totals[name] || 0) + Number(g.Metrics?.UnblendedCost?.Amount || 0);
      }
    }
    fromCe = Object.entries(totals).sort((a, b) => b[1] - a[1]).map(([name]) => name);
    source = 'Cost Explorer (' + fromCe.length + ') + your list (' + manual.length + ')';
  } catch (e) {
    source = 'your list only - Cost Explorer failed: ' + String(e.message).slice(0, 150);
  }
}

// Merge and remove duplicates (case-insensitive)
const seen = new Set();
const services = [...fromCe, ...manual].filter(s => {
  const k = s.toLowerCase();
  if (seen.has(k)) return false;
  seen.add(k);
  return true;
});

if (!services.length) {
  throw new Error('No services to match against. Add services to my_services in Set AWS and Teams Config or enable Cost Explorer.');
}

return [{ json: { services, source } }];

// Keep announcements published within lookback_hours, newest first
const cfg = $('Set AWS and Teams Config').first().json;
const hours = Number(cfg.lookback_hours) || 24;
const max = Number(cfg.max_items) || 50;
const cutoff = Date.now() - hours * 3600 * 1000;

const clean = s => String(s || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const tagText = c => typeof c === 'string' ? c : (c?._ || c?.$?.term || '');

return $input.all()
  .map(i => i.json)
  .map(j => ({ j, t: Date.parse(j.isoDate || j.pubDate) }))
  .filter(x => !isNaN(x.t) && x.t >= cutoff)
  .sort((a, b) => b.t - a.t)
  .slice(0, max)
  .map(({ j }) => ({
    json: {
      title: clean(j.title),
      link: j.link,
      published: j.isoDate || j.pubDate,
      tags: (j.categories || []).map(tagText).filter(Boolean).join(', '),
      text: clean(j.content || j.contentSnippet).slice(0, 2000)
    }
  }));

