  "type": "object",
  "required": ["service", "matched_service", "relevance", "type", "summary", "benefit", "steps", "in_my_region"],
  "properties": {
    "service": {"type": "string", "description": "Main AWS service the announcement is about"},
    "matched_service": {"type": "string", "description": "Exact entry from the team's service list, or empty string"},
    "relevance": {"type": "integer", "minimum": 0, "maximum": 3},
    "type": {"type": "string", "enum": ["new_feature", "region_expansion", "price_change", "deprecation", "security", "other"]},
    "summary": {"type": "string", "description": "What changed, 1-2 very short simple sentences"},
    "benefit": {"type": "string", "description": "How it helps the team, 1-2 very short simple sentences, or empty string"},
    "steps": {"type": "array", "maxItems": 4, "items": {"type": "string"}, "description": "2-4 short steps to start using it, or empty array"},
    "in_my_region": {"type": "string", "enum": ["yes", "no", "unclear"]}
  }
}

