// Verify the AI results, group them and build one Teams Adaptive Card
const cfg = $('Set AWS and Teams Config').first().json;
const svc = $('Build Combined Service List').first().json;
const news = $('Filter by Recent Announcements').all().map(i => i.json);
const ai = $input.all().map(i => i.json.output || null);
const listed = new Set(svc.services.map(s => s.toLowerCase()));
const minRel = Number(cfg.min_relevance) || 2;

// Deterministic check: only count a match if the service really is on the list
const rows = news.map((n, i) => {
  const a = ai[i];
  if (!a) return { ...n, analysed: false, relevance: 0 };
  const matched = String(a.matched_service || '').trim();
  const valid = matched !== '' && listed.has(matched.toLowerCase());
  const relevance = valid ? Math.max(0, Math.min(3, Number(a.relevance) || 0)) : 0;
  return { ...n, ...a, matched_service: valid ? matched : '', relevance, analysed: true };
}).map((r, i) => ({ ...r, uid: 'i' + i }));

const action = rows.filter(r => r.relevance >= 1 && (r.type === 'deprecation' || r.type === 'security'));
const relevant = rows
  .filter(r => !action.includes(r) && r.relevance >= minRel)
  .sort((a, b) => b.relevance - a.relevance);
const others = rows.filter(r => !action.includes(r) && !relevant.includes(r));
const notAnalysed = rows.filter(r => !r.analysed).length;

if (!action.length && !relevant.length && !cfg.post_when_nothing_relevant) {
  return [];
}

const TYPES = {
  new_feature: '🆕 New feature',
  region_expansion: '🌏 Region expansion',
  price_change: '💰 Price change',
  deprecation: '⚠️ Deprecation',
  security: '🔒 Security',
  other: '📌 Update'
};
const region = (String(cfg.my_region).match(/\(([^)]+)\)/) || [])[1] || cfg.my_region;
const text = (t, opts = {}) => ({ type: 'TextBlock', text: String(t ?? ''), wrap: true, ...opts });
const link = r => '[' + String(r.title).replace(/[\[\]]/g, '') + '](' + r.link + ')';

const itemBlock = r => {
  let meta = (TYPES[r.type] || TYPES.other) + ' · ' + (r.matched_service || r.service || '');
  if (r.in_my_region === 'yes') meta += ' · ✅ ' + region;
  if (r.in_my_region === 'no') meta += ' · not in ' + region + ' yet';
  const items = [
    text(link(r), { weight: 'Bolder' }),
    text(meta, { isSubtle: true, size: 'Small', spacing: 'None' }),
    text(r.summary, { spacing: 'Small' })
  ];
  if (r.benefit) items.push(text('💡 **How it helps:** ' + r.benefit, { spacing: 'Small' }));
  const steps = (Array.isArray(r.steps) ? r.steps : []).filter(Boolean).slice(0, 4);
  if (steps.length) {
    const sid = 'steps_' + r.uid;
    items.push({ type: 'ActionSet', spacing: 'Small', actions: [{ type: 'Action.ToggleVisibility', title: '🛠 How to use it', targetElements: [sid] }] });
    items.push({ type: 'Container', id: sid, isVisible: false, style: 'emphasis', items: [
      ...steps.map((s, k) => text((k + 1) + '. ' + s, { spacing: k === 0 ? 'None' : 'Small' })),
      text('[Read the full announcement](' + r.link + ')', { size: 'Small', isSubtle: true, spacing: 'Small' })
    ] });
  }
  return { type: 'Container', spacing: 'Medium', items };
};

// $now follows the timezone set in the workflow settings
const today = $now.toFormat('yyyy-MM-dd');
const body = [
  text('AWS News Digest', { size: 'Large', weight: 'Bolder' }),
  text(today + ' · ' + (action.length + relevant.length) + ' of ' + rows.length + ' announcements matter to you', { isSubtle: true, spacing: 'None' })
];

if (action.length) {
  body.push(text('Action needed', { size: 'Medium', weight: 'Bolder', color: 'Attention', separator: true, spacing: 'Large' }));
  action.forEach(r => body.push(itemBlock(r)));
}
if (relevant.length) {
  body.push(text('Relevant to you', { size: 'Medium', weight: 'Bolder', separator: true, spacing: 'Large' }));
  relevant.forEach(r => body.push(itemBlock(r)));
}
if (!action.length && !relevant.length) {
  body.push(text('Nothing relevant to your services today.', { separator: true, spacing: 'Large' }));
}
if (others.length) {
  const shown = others.slice(0, 40);
  body.push({ type: 'ActionSet', separator: true, spacing: 'Large', actions: [{ type: 'Action.ToggleVisibility', title: 'Show ' + others.length + ' other announcements', targetElements: ['others'] }] });
  body.push({ type: 'Container', id: 'others', isVisible: false, items: [
    ...shown.map(r => text('• ' + link(r), { size: 'Small', spacing: 'Small' })),
    ...(others.length > shown.length ? [text('…and ' + (others.length - shown.length) + ' more', { isSubtle: true, size: 'Small' })] : [])
  ] });
}

let footer = 'Checked ' + rows.length + ' announcements from the last ' + cfg.lookback_hours + ' h against ' + svc.services.length + ' services (' + svc.source + ').';
if (notAnalysed) footer += ' ' + notAnalysed + ' could not be analysed and are listed under other announcements.';
body.push(text(footer, { isSubtle: true, size: 'Small', separator: true, spacing: 'Large' }));

const payload = {
  type: 'message',
  attachments: [{
    contentType: 'application/vnd.microsoft.card.adaptive',
    contentUrl: null,
    content: {
      $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
      type: 'AdaptiveCard',
      version: '1.4',
      msteams: { width: 'Full' },
      body
    }
  }]
};

return [{ json: { payload, action: action.length, relevant: relevant.length, total: rows.length } }];
